def get_crop_alert(crop_name: str, language: str = "en") -> Dict[str, Any]:
    norm_lang = (language or "en").lower().strip()
    clean_crop = crop_name.lower().strip()
    curr_month = datetime.now().month
    cal = crop_calendar.get(clean_crop)
    loc_crop = get_crop_display_name(crop_name, norm_lang)

    def _get_msg_and_rec(alert_key: str) -> tuple:
        tpl = CROP_ALERT_TEMPLATES.get(alert_key, CROP_ALERT_TEMPLATES["general_monitoring"])
        entry = tpl.get(norm_lang) or tpl.get("en")
        msg = entry[0].format(crop=loc_crop)
        rec = entry[1].format(crop=loc_crop)
        return msg, rec

    if not cal:
        msg, rec = _get_msg_and_rec("general_monitoring")
        return {
            "crop": loc_crop,
            "raw_crop": crop_name,
            "alert_type": "general_monitoring",
            "message": msg,
            "recommendation": rec
        }
    harvest_months = cal.get("harvest", [])
    sow_months = cal.get("sow", [])
    if curr_month in harvest_months:
        msg, rec = _get_msg_and_rec("harvest_approaching")
        alert_type = "harvest_approaching"
    elif any(abs(curr_month - hm) <= 1 for hm in harvest_months):
        msg, rec = _get_msg_and_rec("pre_harvest_window")
        alert_type = "pre_harvest_window"
    elif curr_month in sow_months:
        msg, rec = _get_msg_and_rec("sowing_season")
        alert_type = "sowing_season"
    else:
        msg, rec = _get_msg_and_rec("post_harvest_storage")
        alert_type = "post_harvest_storage"

    return {
        "crop": loc_crop,
        "raw_crop": crop_name,
        "alert_type": alert_type,
        "message": msg,
        "recommendation": rec
    }
